/// <summary>
/// METCoverNoteDP
/// </summary>
[SrsReportParameterAttribute(classStr(METCoverNoteContract))]
public class METCoverNoteDP extends SRSReportDataProviderBase
{
    METCoverNoteContract        contract;
    METCoverNoteHeaderTmp       headerTmp;
    METCoverNoteProductTypesTmp productTypesTmp;
    METCoverNoteSalesOrdersTmp  salesOrdersTmp;
    METCoverNoteTotesTmp        totesTmp;

}

Method.Source:
    /// <summary>
    /// processReport
    /// </summary>
    public void processReport()
    {
        CompanyInfo           companyInfo = CompanyInfo::find();
        METIndustryKeyLogo    reportLogo;
        Image                 img;
        METShipmentTable      shipmentTable;
        METShipmentLine       shipmentLine;
        MetContainerTable     containerTable;
        METContainerTypeTable containerType;
        METIndustryKeyTable   industryKeyTable;
        CustTable             custTable;
        METCustTable          metCustTable;
        SalesTable            salesTable;
        InventLocation        inventLocation;
        InventLocationId      inventLocationId;
        CustParameters        custParameters;
        Qty                   securityCartons;
        TMSCarrier            tmsCarrier;

        contract = this.parmDataContract() as METCoverNoteContract;

        select firstonly shipmentTable
            where shipmentTable.ShipmentId == contract.parmShipmentId()
                join tmsCarrier
                    where tmsCarrier.CarrierCode == shipmentTable.CarrierCode;

        select firstonly custTable
            join metCustTable
                where custTable.AccountNum == shipmentTable.CustAccount
                   && custTable.AccountNum == metCustTable.AccountNum;

        select firstonly industryKeyTable
            where industryKeyTable.IndustryKey == metCustTable.IndustryKey;

        select firstonly custParameters;

        reportLogo = industryKeyTable.Logo;

        switch(reportLogo)
        {
            case METIndustryKeyLogo::Logo1:
                img = CompanyImage::metGetImage(companyInfo);
                break;
            case METIndustryKeyLogo::Logo2:
                img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo);
                break;
            case METIndustryKeyLogo::Logo3:
                img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo3);
                break;
            case METIndustryKeyLogo::Logo4:
                img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo4);
                break;
            default:
                img = CompanyImage::metGetImage(companyInfo);
                break;
        }

        if(img)
        {
            headerTmp.CompanyLogo = img.getData();
        }
        headerTmp.CompanyName = industryKeyTable.CompanyName;
        headerTmp.CompanyABN = industryKeyTable.CoRegNum;

        headerTmp.CustomerServicePhone = industryKeyTable.CarrierDocumentPhone;
        headerTmp.PODNumber =  METCoverNoteDP::getNumberSeq();
        headerTmp.Revision = custParameters.METRevision;
        headerTmp.RevisionDate = custParameters.METRevisionDate;
        headerTmp.DocumentNumber = custParameters.METDocumentNumber;

        headerTmp.CustomerAccountNumber = custTable.AccountNum;
        headerTmp.CustomerName = custTable.name();
        headerTmp.CustomerAddress = custTable.mcrDefaultDeliveryPostalAddress().Address;
        headerTmp.CustomerPhone = custTable.phone();
        headerTmp.ReportDateTime = DateTimeUtil::getSystemDateTime();
        headerTmp.ReportUser = XUserInfo::find(false, curUserId()).name;
        headerTmp.WareHouseInstruction = metCustTable.WareHouseInstruction;
        headerTmp.SpecialInstruction = metCustTable.SpecialInstruction;

        while select containerTable
            where containerTable.MetShipmentId == shipmentTable.ShipmentId
        {
            if(containerTable.ContainerTypeCode == 'CHP')
            {
                headerTmp.ChepPalletCount = containerTable.MetContainerQty;
            }
            else if(containerTable.ContainerTypeCode == 'LOS')
            {
                headerTmp.LoscamPalletCount = containerTable.MetContainerQty;
            }
            else if(containerTable.ContainerTypeCode == 'LFT')
            {
                headerTmp.PalletLiftCount = containerTable.MetContainerQty;
            }
            else if(containerTable.ContainerTypeCode == 'BLT')
            {
                headerTmp.CoolerBlanketCount = containerTable.MetContainerQty;
            }
            else if(containerTable.ContainerTypeCode == 'PLN')
            {
                headerTmp.PlainPalletCount = containerTable.MetContainerQty;
            }
            //securityCartons = containerTable.
        }

        while select shipmentLine
            where shipmentLine.ShipmentId == shipmentTable.ShipmentId
        {
            if(!inventLocationId)
            {
                select firstonly salesTable
                    where salesTable.SalesId == shipmentLine.SalesId;

                inventLocationId = salesTable.InventLocationId;
            }
            salesOrdersTmp.clear();
            salesOrdersTmp.SalesId = shipmentLine.SalesId;
            salesOrdersTmp.insert();

            this.addProductTypes(shipmentLine.SalesId);
        }

        if(inventLocationId)
        {
            select firstonly inventLocation
                where inventLocation.InventLocationId == inventLocationId;

            headerTmp.WarehouseName = inventLocation.Name;
            headerTmp.WarehouseAddress = inventLocation.address();

            while select containerType
                where containerType.InventLocationId == inventLocationId
            {
                if(containerType.ContainerTypeCode == 'CHP')
                {
                    headerTmp.PalletContainerWeight = headerTmp.PalletContainerWeight + (headerTmp.ChepPalletCount * containerType.Weight);
                }
                else if(containerType.ContainerTypeCode == 'LOS')
                {
                    headerTmp.PalletContainerWeight = headerTmp.PalletContainerWeight + (headerTmp.LoscamPalletCount * containerType.Weight);
                }
                else if(containerType.ContainerTypeCode == 'LFT')
                {
                    headerTmp.PalletContainerWeight = headerTmp.PalletContainerWeight + (headerTmp.PalletLiftCount * containerType.Weight);
                }
                else if(containerType.ContainerTypeCode == 'BLT')
                {
                    headerTmp.PalletContainerWeight = headerTmp.PalletContainerWeight + (headerTmp.CoolerBlanketCount * containerType.Weight);
                }
                else if(containerType.ContainerTypeCode == 'PLN')
                {
                    headerTmp.PalletContainerWeight = headerTmp.PalletContainerWeight + (headerTmp.PlainPalletCount * containerType.Weight);
                }
            }
        }

        headerTmp.SecurityCartons = 1;
        headerTmp.CarrierName = tmsCarrier.Name;
        headerTmp.RunNumber = shipmentTable.RouteStop;
        headerTmp.insert();
    }

    /// <summary>
    /// add ProductTypes
    /// </summary>
    /// <param name = "_salesId">sales order number</param>
    public void addProductTypes(SalesId _salesId)
    {
        SalesLine       salesLine;
        METSalesLine    metSalesLine;
        InventDim       inventDim;
        MetItemSiteSettingsSetup    itemSiteSettingsSetup;

        while select salesLine
             where salesLine.SalesId == _salesId
                join metSalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                join inventDim
                    where inventDim.inventDimId == salesLine.InventDimId
                join itemSiteSettingsSetup
                    where itemSiteSettingsSetup.ItemId == salesLine.ItemId
                       && itemSiteSettingsSetup.InventSiteId == inventDim.InventSiteId

        {
            productTypesTmp.clear();
            productTypesTmp.ProductType = itemSiteSettingsSetup.ItemType;
            productTypesTmp.GrossWeight = salesLine.displayMETGrossWeight();
            productTypesTmp.METCase = salesLine.displayMETcases();
            productTypesTmp.BrokenCase = salesLine.displayMETBrokenCase();
            productTypesTmp.insert();
        
        }
    }

/// <summary>
/// productTypesTmp
/// </summary>
/// <returns>METCoverNoteProductTypesTmp</returns>
[SrsReportDataSet(tableStr(METCoverNoteProductTypesTmp))]
public METCoverNoteProductTypesTmp getLinesTmp()
{
    select productTypesTmp;
    return productTypesTmp;
}

/// <summary>
/// getHeaderTmp
/// </summary>
/// <returns>METCoverNoteHeaderTmp</returns>
[SrsReportDataSet(tableStr(METCoverNoteHeaderTmp))]
public METCoverNoteHeaderTmp getHeaderTmp()
{
    select headerTmp;
    return headerTmp;
}

/// <summary>
/// getReasonsTmp
/// </summary>
/// <returns>METCoverNoteSalesOrdersTmp</returns>
[SrsReportDataSet(tableStr(METCoverNoteSalesOrdersTmp))]
public METCoverNoteSalesOrdersTmp getSalesOrdersTmp()
{
    select salesOrdersTmp;
    return salesOrdersTmp;
}

/// <summary>
/// getReasonsTmp
/// </summary>
/// <returns>METCoverNoteTotesTmp</returns>
[SrsReportDataSet(tableStr(METCoverNoteTotesTmp))]
public METCoverNoteTotesTmp getTotesTmpTmp()
{
    select totesTmp;
    return totesTmp;
}

    /// <summary>
    /// Get the number sequence id
    /// </summary>
    /// <returns>the number sequence number</returns>
    public static METProofOfDocNumber getNumberSeq()
    {
        NumberSequenceReference     numberSequenceReference;
        NumberSeq                   numberSeq;

        numberSequenceReference = CustParameters::numRefMETProofOfDocNumber();
        
        if (numberSequenceReference)
        {
            numberSeq = NumberSeq::newGetNum(numberSequenceReference);
        }

        if(!numberSeq)
        {
            error("@MET:ChangeTrackNumberIdNumSeqFailed");
            throw Exception::Error;
        }

        return numberSeq.num();
    }
